#!/bin/bash

set -e
set -o pipefail
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
LEGACY_UPGRADE=false
FRESH_INSTALL=true
PARTIAL_INSTALL_RESUME=false
PARTIAL_INSTALL_MARKER_PRESENT=false
LEGACY_PARTIAL_ADOPTED=false

#################################################
#               USER VARIABLES                  #
#  These will be prompted interactively          #
#################################################

# Pin the reviewed application release; update explicitly for a new release.
APP_VERSION="v1.23.2-lic-3"
LICENSE_TRUSTED_KEY_ID="${LICENSE_TRUSTED_KEY_ID-adanware-prod-v2}"
PRODUCTION_KEY_IDS=(adanware-prod-v2 production-2026)
PRODUCTION_FINGERPRINTS=(d77cd0fbc4b570191f811117bede664cf495eb4e48ea4571552c7d856f46911e a1dae0d846ac59f26541d49b8b7d6264949a54b8dedfc28c08875c7703480244)
PRODUCTION_KEY_PEMS=($'-----BEGIN PUBLIC KEY-----\nMCowBQYDK2VwAyEAkWCN3qr1qhUyPW4J6h6i0jjccX0LvP6MLWTA7Lu7lt0=\n-----END PUBLIC KEY-----' $'-----BEGIN PUBLIC KEY-----\nMCowBQYDK2VwAyEA8Qo2UTtdSNsD2rhZAL+8ZaGfX7F3PATbomlGriiMxfY=\n-----END PUBLIC KEY-----')
validate_jwt_secret_env() {
    local env_file="$1" count
    count=$(grep -c '^JWT_SECRET_KEY=' "$env_file" || true)
    [ "$count" -eq 1 ] && grep -Eq '^JWT_SECRET_KEY=[[:xdigit:]]{64}$' "$env_file" || {
        echo "❌ Existing JWT_SECRET_KEY must be exactly one 256-bit hexadecimal value; refusing deployment." >&2
        return 1
    }
}
validate_safe_install_env() {
    local env_file="$1" line value name
    validate_jwt_secret_env "$env_file" || return 1
    while IFS= read -r line || [ -n "$line" ]; do
        case "$line" in
            ""|\#*) ;;
            POSTGRES_DB=*) [[ "${line#*=}" =~ ^[A-Za-z_][A-Za-z0-9_]{0,52}$ ]] || return 1 ;;
            POSTGRES_USER=*) [[ "${line#*=}" =~ ^[A-Za-z_][A-Za-z0-9_]{0,31}$ ]] || return 1 ;;
            POSTGRES_PASSWORD=*) [[ "${line#*=}" =~ ^[A-Za-z0-9_-]{20,64}$ ]] || return 1 ;;
            JWT_SECRET_KEY=*) [[ "${line#*=}" =~ ^[[:xdigit:]]{64}$ ]] || return 1 ;;
            TANDD_COORDINATOR_PG_PORT=55432|TANDD_BACKUP_POSTGRES_USER=tandd_backup|BACKUP_RETENTION_DAYS=7) ;;
            TANDD_APP_DATABASE_URL=*) [[ "${line#*=}" =~ ^postgresql://tandd_(cutover|app):[[:xdigit:]]{64}@postgres:5432/[A-Za-z_][A-Za-z0-9_]{0,52}$ ]] || return 1 ;;
            TANDD_APP_PASSWORD=*|TANDD_BACKUP_POSTGRES_PASSWORD=*|TANDD_STAGING_PASSWORD=*|TANDD_CUTOVER_PASSWORD=*)
                value="${line#*=}"
                [ -z "$value" ] || [[ "$value" =~ ^[[:xdigit:]]{64}$ ]] || return 1
                ;;
            *) return 1 ;;
        esac
    done < "$env_file"
    for name in POSTGRES_DB POSTGRES_USER POSTGRES_PASSWORD JWT_SECRET_KEY; do
        [ "$(grep -c "^${name}=" "$env_file" || true)" -eq 1 ] || return 1
    done
}
classify_existing_app_image() {
    case "$1" in
        ghcr.io/dev-adanware/tanddsrv:1.23.1)
            LEGACY_UPGRADE=true
            ;;
        ghcr.io/dev-adanware/tanddsrv:v1.23.2-lic-2|ghcr.io/dev-adanware/tanddsrv:v1.23.2-lic-3|ghcr.io/dev-adanware/tanddsrv:${APP_VERSION})
            ;;
        *)
            echo "❌ Existing application image is not a supported baseline or pinned target." >&2
            return 1
            ;;
    esac
}
prepare_embedded_assets() {
    for tool in base64 sha256sum mktemp chmod rm; do
        command -v "$tool" >/dev/null 2>&1 || { echo "❌ Required embedded-asset tool unavailable: $tool" >&2; return 1; }
    done
    EMBEDDED_ASSET_DIR="$(mktemp -d "${TMPDIR:-/tmp}/amt-tandd-lic3-assets.XXXXXX")" || return 1
    trap 'rm -rf -- "$EMBEDDED_ASSET_DIR"' EXIT
    chmod 0700 "$EMBEDDED_ASSET_DIR" || return 1
