publish_embedded_asset() {
    local name="$1" destination_dir="$2" mode="$3" destination temporary expected actual
    [[ "$name" =~ ^[A-Za-z0-9._-]+$ ]] || return 1
    destination="$destination_dir/$name"
    expected="$(embedded_asset_hash "$name")" || return 1
    sudo install -d -o root -g root -m 0750 "$destination_dir" || return 1
    if sudo test -L "$destination" || { sudo test -e "$destination" && ! sudo test -f "$destination"; }; then
        echo "❌ Existing embedded artifact destination is unsafe: $name" >&2; return 1
    fi
    temporary="$(sudo mktemp "$destination_dir/.$name.XXXXXX")" || return 1
    if ! sudo install -o root -g root -m "$mode" "$EMBEDDED_ASSET_DIR/$name" "$temporary"; then
        sudo rm -f -- "$temporary"; return 1
    fi
    actual="$(sudo sha256sum "$temporary" | awk '{print $1}')" || actual=
    if [ "$actual" != "$expected" ]; then
        sudo rm -f -- "$temporary"
        echo "❌ Staged embedded artifact checksum failed: $name" >&2; return 1
    fi
    if ! sudo mv -fT -- "$temporary" "$destination"; then
        sudo rm -f -- "$temporary"
        echo "❌ Could not atomically publish embedded artifact: $name" >&2; return 1
    fi
}
embedded_asset_hash() {
    case "$1" in
        coordinator.py) printf %s 06c379fa2f8ac7e443aa41ffe566e2b194f85692dcd8b257a7edbdb60c1c079c ;;
        preflight.py) printf %s 1d5a770f63f39108a260e2c817ebbf6c9e473883feb65399264c8cc8e20cfe46 ;;
        validation.py) printf %s 4481dd210a8ef68a72664d6a9bf1bacc1053ec56e6ac2afc1c3b0dc4a63cd0bc ;;
        maintenance.py) printf %s fe71bfe8bab151f773df8476c68acd4e6686bbac982cd021254d347bdfe48ee6 ;;
        cutover.py) printf %s 11d91aea9ccaa537696edda22805c1ca1fe0732daff09caed084b2337dcc9dcc ;;
        fresh_database.sh) printf %s 67e9f4151092d7375afa3c445bed9fdd57d5bfff5d4b0fadf34207d7bbff41f0 ;;
        postgres_client.sh) printf %s aa6180ee4adfa3ec1dde9506d1460b3325e5c033eec6f3815365dffb0a3c5f9b ;;
        provision.sh) printf %s d317cc67f6171c23b76b887d0a402dbba03598759ecaa90b69d0fca890284785 ;;
        OPERATOR_PROVISIONING.md) printf %s 2effc029ac020b3f410ba2e8b5fc0b330c10729c624913a76004fd5df724a34a ;;
        migrate_legacy_identity.sh) printf %s ce44bc0a8f9e0ebebf7c26629f48ea9448cc8fd9799adcf4a4220c0734568a22 ;;
        *) return 1 ;;
    esac
}
partial_install_marker_is_valid() {
    local root="$1" marker entries entry path
    marker="$root/.lic3-install-in-progress"
    sudo test -d "$root" && ! sudo test -L "$root" || return 1
    sudo test -f "$marker" && ! sudo test -L "$marker" || return 1
    [ "$(sudo stat -c '%u:%a' "$marker" 2>/dev/null)" = "0:600" ] || return 1
    [ "$(sudo cat "$marker" 2>/dev/null)" = "amt-tandd-lic3-fresh-install-v1" ] || return 1
    entries="$(sudo find "$root" -mindepth 1 -maxdepth 1 -printf '%f\n' 2>/dev/null | sort)" || return 1
    while IFS= read -r entry; do
        [ -n "$entry" ] || continue
        case "$entry" in
            .lic3-install-in-progress|.lic3-marker.*|.env|.env.tmp.*|docker-compose.yml|backup_postgres.sh|tandd-data|ssl-certs|licensing|restore_coordinator) ;;
            *) return 1 ;;
        esac
    done <<< "$entries"
    for path in "$root/tandd-data" "$root/ssl-certs" "$root/licensing" "$root/licensing/public_keys" "$root/restore_coordinator"; do
        if sudo test -e "$path" || sudo test -L "$path"; then
            sudo test -d "$path" && ! sudo test -L "$path" || return 1
        fi
    done
    for path in "$root/.env" "$root/docker-compose.yml" "$root/backup_postgres.sh" "$root/licensing/registry.json"; do
        if sudo test -e "$path" || sudo test -L "$path"; then
            sudo test -f "$path" && ! sudo test -L "$path" || return 1
        fi
    done
    if sudo test -e "$root/.env"; then
        validate_safe_install_env "$root/.env" || return 1
    fi
    return 0
}
legacy_partial_install_is_safe_to_adopt() {
    local root="$1" entries expected key_dir key_file actual expected_registry contents
    sudo test -d "$root" && ! sudo test -L "$root" || return 1
    sudo test -e "$root/.lic3-install-in-progress" && return 1
    entries="$(sudo find "$root" -mindepth 1 -maxdepth 1 -printf '%f\n' 2>/dev/null | sort)" || return 1
    expected="$(printf '%s\n' .env backup_postgres.sh licensing restore_coordinator ssl-certs tandd-data | sort)"
    [ "$entries" = "$expected" ] || return 1
    for path in "$root/licensing" "$root/licensing/public_keys" "$root/restore_coordinator" "$root/ssl-certs" "$root/tandd-data" "$root/tandd-data/backups" "$root/tandd-data/licensing"; do
        sudo test -d "$path" && ! sudo test -L "$path" || return 1
    done
    for path in "$root/.env" "$root/backup_postgres.sh"; do
        sudo test -f "$path" && ! sudo test -L "$path" || return 1
    done
    validate_safe_install_env "$root/.env" || return 1
    key_dir="$root/licensing/public_keys"
    for index in "${!PRODUCTION_KEY_IDS[@]}"; do
        key_file="$key_dir/${PRODUCTION_KEY_IDS[$index]}.pem"
        sudo test -f "$key_file" && ! sudo test -L "$key_file" || return 1
        actual="$(sudo openssl pkey -pubin -in "$key_file" -outform DER 2>/dev/null | sha256sum | awk '{print $1}')" || return 1
        [ "$actual" = "${PRODUCTION_FINGERPRINTS[$index]}" ] || return 1
    done
    entries="$(sudo find "$key_dir" -mindepth 1 -maxdepth 1 -printf '%f\n' 2>/dev/null | sort)" || return 1
    expected="$(printf '%s\n' adanware-prod-v2.pem production-2026.pem registry.json | sort)"
    [ "$entries" = "$expected" ] || return 1
    expected_registry='{"format_version":1,"keys":[{"key_id":"adanware-prod-v2","file":"adanware-prod-v2.pem","der_sha256":"d77cd0fbc4b570191f811117bede664cf495eb4e48ea4571552c7d856f46911e","usage":"sign-and-verify"},{"key_id":"production-2026","file":"production-2026.pem","der_sha256":"a1dae0d846ac59f26541d49b8b7d6264949a54b8dedfc28c08875c7703480244","usage":"verify-only","source_archive_sha256":"43eb130aadd3c8636014cb62ed364ddb405f4619be29206da89946cbc3a5df9a"}]}'
    contents="$(sudo cat "$key_dir/registry.json")" || return 1
    [ "$contents" = "$expected_registry" ] || return 1
    [ -z "$(sudo find "$root/restore_coordinator" -mindepth 1 -print -quit 2>/dev/null)" ] || return 1
    return 0
}
legacy_partial_install_preflight_adopt() {
    local root="$1"
    if sudo docker volume inspect amt-tandd_postgres_data >/dev/null 2>&1; then
        echo "❌ The old partial-install state has a PostgreSQL volume; refusing adoption." >&2
        return 1
    fi
    legacy_partial_install_is_safe_to_adopt "$root"
}
create_partial_install_marker() {
    local root="$1" marker temporary
    marker="$root/.lic3-install-in-progress"
    if sudo test -L "$root" || { sudo test -e "$root" && ! sudo test -d "$root"; }; then
        echo "❌ Partial-install root is unsafe." >&2; return 1
    fi
    sudo install -d -o root -g root -m 0750 "$root" || return 1
    if sudo test -e "$marker" || sudo test -L "$marker"; then
        partial_install_marker_is_valid "$root" || {
            echo "❌ Existing partial-install marker is invalid; refusing to resume." >&2; return 1;
        }
        PARTIAL_INSTALL_RESUME=true
        PARTIAL_INSTALL_MARKER_PRESENT=true
        return 0
    fi
    temporary="$(sudo mktemp "${root}/.lic3-marker.XXXXXX")" || return 1
    if ! printf '%s\n' amt-tandd-lic3-fresh-install-v1 | sudo tee "$temporary" >/dev/null; then
        sudo rm -f -- "$temporary"; return 1
    fi
    sudo chmod 0600 "$temporary" || { sudo rm -f -- "$temporary"; return 1; }
    if ! sudo ln -- "$temporary" "$marker"; then
        sudo rm -f -- "$temporary"
        partial_install_marker_is_valid "$root" || return 1
        PARTIAL_INSTALL_RESUME=true
        PARTIAL_INSTALL_MARKER_PRESENT=true
        return 0
    fi
    sudo rm -f -- "$temporary"
    PARTIAL_INSTALL_MARKER_PRESENT=true
}
cleanup_partial_install_temps() {
    local root="$1" pattern candidate
    local patterns=(
        "$root/.lic3-marker.*"
        "$root/.env.tmp.*"
        "$root/licensing/public_keys/.adanware-prod-v2.pem.tmp.*"
        "$root/licensing/public_keys/.production-2026.pem.tmp.*"
        "$root/licensing/public_keys/.registry.json.tmp.*"
        "$root/restore_coordinator/.coordinator.py.*"
        "$root/restore_coordinator/.preflight.py.*"
        "$root/restore_coordinator/.validation.py.*"
        "$root/restore_coordinator/.maintenance.py.*"
        "$root/restore_coordinator/.cutover.py.*"
        "$root/restore_coordinator/.fresh_database.sh.*"
        "$root/restore_coordinator/.postgres_client.sh.*"
        "$root/restore_coordinator/.provision.sh.*"
        "$root/restore_coordinator/.OPERATOR_PROVISIONING.md.*"
    )
    for pattern in "${patterns[@]}"; do
        for candidate in $pattern; do
            if sudo test -e "$candidate" || sudo test -L "$candidate"; then
                sudo test -f "$candidate" && ! sudo test -L "$candidate" || {
                    echo "❌ Unsafe interrupted-install temporary file; refusing resume." >&2; return 1;
                }
                sudo rm -f -- "$candidate" || return 1
            fi
        done
    done
}
remove_partial_install_marker() {
    local root="$1" marker
    marker="$root/.lic3-install-in-progress"
    if sudo test -e "$marker" || sudo test -L "$marker"; then
        partial_install_marker_is_valid "$root" || {
            echo "❌ Partial-install marker changed; leaving it for safe recovery." >&2; return 1;
        }
        sudo rm -f -- "$marker"
    fi
}
print_partial_container_recovery() {
    echo "❌ A LIC-3 marked installation has a partial Compose container set; automatic database provisioning is unsafe." >&2
    echo "After confirming this is the intended amt-tandd project, stop and remove only its containers (the named PostgreSQL volume and host data are retained):" >&2
    echo "  sudo docker compose --project-name amt-tandd --project-directory /opt/amt-tandd --file /opt/amt-tandd/docker-compose.yml stop" >&2
    echo "  sudo docker compose --project-name amt-tandd --project-directory /opt/amt-tandd --file /opt/amt-tandd/docker-compose.yml rm -f" >&2
    echo "Then rerun this installer. Do not use 'down -v' or remove the PostgreSQL volume or /opt/amt-tandd/tandd-data." >&2
}
prepare_embedded_assets || exit 1
if [ "${1:-}" = "--verify-embedded-assets" ]; then
    for name in coordinator.py preflight.py validation.py maintenance.py cutover.py fresh_database.sh postgres_client.sh provision.sh OPERATOR_PROVISIONING.md migrate_legacy_identity.sh; do
        printf "%s %s\n" "$name" "$(embedded_asset_hash "$name")"
    done
    exit 0
fi

if [[ ! "$LICENSE_TRUSTED_KEY_ID" =~ ^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$ ]] || [ "$LICENSE_TRUSTED_KEY_ID" != "${PRODUCTION_KEY_IDS[0]}" ]; then
    echo "❌ LICENSE_TRUSTED_KEY_ID must be the approved issuance key ${PRODUCTION_KEY_IDS[0]}" >&2
    exit 2
fi

# PostgreSQL Database Settings (auto-generated if not set)
POSTGRES_DB="tandd"
POSTGRES_USER="tandd_user"
POSTGRES_PASSWORD=""  # Leave empty to auto-generate secure password

# SSL Certificate Information (for CSR generation)
# Leave empty to auto-detect server hostname
SSL_HOSTNAME=""           # e.g., "shf-tms-01" or "tandd.company.com"
SSL_COUNTRY="SA"          # Two-letter country code (SA = Saudi Arabia)
SSL_STATE="Riyadh"        # State or Province
SSL_CITY="Riyadh"         # City
SSL_ORGANIZATION="ADANWARE"  # Company name

#################################################
#              DO NOT EDIT BELOW                #
#################################################

echo "============================================="
echo "      AMT-T&D Automated Deployment"
echo "           Powered by ADANWARE"
echo "============================================="

### -------------------------------
### 1. INTERACTIVE SETUP PROMPTS
### -------------------------------

echo ""
echo "---------------------------------------------"
echo "📋 SETUP CONFIGURATION"
echo "---------------------------------------------"

# Prompt for NTP Server
if [ -z "${NTP_SERVER:-}" ]; then
    read -rp "🌐 Enter your NTP server IP or hostname [192.168.0.1]: " NTP_INPUT
    NTP_SERVER="${NTP_INPUT:-192.168.0.1}"
fi
echo "  ✓ NTP Server: $NTP_SERVER"

# Prompt for GitHub credentials
echo ""
echo "🔐 GitHub credentials required to download the application:"
read -rp "   GitHub Username [Dev-Adanware]: " GH_USER_INPUT
GITHUB_USERNAME="${GH_USER_INPUT:-Dev-Adanware}"
read -rp "   GitHub Token: " GITHUB_TOKEN
echo ""

if [ -z "$GITHUB_TOKEN" ]; then
    echo "❌ GitHub token is required. Please provide a valid token."
    exit 1
fi
echo "  ✓ GitHub credentials received"
echo ""

### -------------------------------
### 2. PREREQUISITE CHECKS
### -------------------------------

echo "Checking system prerequisites..."
# Check Linux
if [[ "$(uname -s)" != "Linux" ]]; then
    echo "❌ This script must run on Linux."
    exit 1
else
    echo "✅ Linux OS verified"
fi

# Check RAM ≥ 2GB
TOTAL_RAM=$(free -m | awk '/Mem:/ {print $2}')
if [ "$TOTAL_RAM" -lt 2000 ]; then
    echo "❌ Minimum 2GB RAM required. Current: ${TOTAL_RAM}MB"
    exit 1
else
    echo "✅ RAM check passed (${TOTAL_RAM}MB)"
fi

# Check Disk ≥ 20GB
AVAILABLE_DISK=$(df -BG / | awk 'NR==2 {print $4}' | sed 's/G//')
if [ "$AVAILABLE_DISK" -lt 5 ]; then
    echo "❌ Minimum 5GB free disk space required. Available: ${AVAILABLE_DISK}GB"
    exit 1
else
    echo "✅ Disk space check passed (${AVAILABLE_DISK}GB free)"
fi

# Check Docker installed
if ! command -v docker &> /dev/null; then
    echo "❌ Docker is not installed."
    exit 1
fi

# Check Docker version ≥ 20.10
DOCKER_VERSION=$(docker --version | awk '{print $3}' | sed 's/,//')
REQUIRED_VERSION="20.10"

if [[ "$(printf '%s\n' "$REQUIRED_VERSION" "$DOCKER_VERSION" | sort -V | head -n1)" != "$REQUIRED_VERSION" ]]; then
    echo "❌ Docker 20.10+ required. Current version: $DOCKER_VERSION"
    exit 1
else
    echo "✅ Docker version verified ($DOCKER_VERSION)"
fi

# Detect and validate an existing stack before creating/changing any files.
if project_containers=$(sudo docker ps -a --filter 'label=com.docker.compose.project=amt-tandd' --format '{{.Names}}' | sort); then
    if [ -n "$project_containers" ]; then
        partial_marker=/opt/amt-tandd/.lic3-install-in-progress
        if sudo test -e "$partial_marker" || sudo test -L "$partial_marker"; then
            if partial_install_marker_is_valid /opt/amt-tandd; then
                print_partial_container_recovery
            else
                echo "❌ Partial-install marker or layout is unsafe; refusing automatic recovery." >&2
            fi
            exit 1
        fi
        FRESH_INSTALL=false
        expected_containers=$(printf '%s\n' tandd-app tandd-backup tandd-postgres | sort)
        if [ "$project_containers" != "$expected_containers" ]; then
            echo "❌ Existing Compose project has unexpected or missing containers; refusing upgrade."
            exit 1
        fi
        active_image=$(sudo docker inspect --format '{{.Config.Image}}' tandd-app)
        if ! classify_existing_app_image "$active_image"; then
            exit 1
        fi
        for pair in tandd-app:app tandd-postgres:postgres tandd-backup:backup; do
            container=${pair%%:*}
            service=${pair#*:}
            project=$(sudo docker inspect --format '{{ index .Config.Labels "com.docker.compose.project" }}' "$container")
            actual_service=$(sudo docker inspect --format '{{ index .Config.Labels "com.docker.compose.service" }}' "$container")
            state=$(sudo docker inspect --format '{{.State.Status}}' "$container")
            if [ "$project" != amt-tandd ] || [ "$actual_service" != "$service" ]; then
                echo "❌ Existing container $container has unexpected Compose identity."
                exit 1
            fi
            if [ "$container" != tandd-backup ] && [ "$state" != running ]; then
                echo "❌ Existing application/PostgreSQL container $container is not running."
                exit 1
            fi
        done
        [ -f /opt/amt-tandd/docker-compose.yml ] && [ ! -L /opt/amt-tandd/docker-compose.yml ] && \
            [ -f /opt/amt-tandd/.env ] && [ ! -L /opt/amt-tandd/.env ] && \
            [ -d /opt/amt-tandd/tandd-data ] && [ ! -L /opt/amt-tandd/tandd-data ] && \
            [ -d /opt/amt-tandd/tandd-data/backups ] && [ ! -L /opt/amt-tandd/tandd-data/backups ] && \
            [ -d /opt/amt-tandd/ssl-certs ] && [ ! -L /opt/amt-tandd/ssl-certs ] || {
            echo "❌ Existing Compose, credentials, data, backups, or SSL paths are missing or unsafe."
            exit 1
        }
        for setting in POSTGRES_DB POSTGRES_USER POSTGRES_PASSWORD; do
            grep -Eq "^${setting}=.+$" /opt/amt-tandd/.env || {
                echo "❌ Existing .env is missing a non-empty ${setting}."; exit 1;
            }
        done
        sudo docker compose --project-name amt-tandd --file /opt/amt-tandd/docker-compose.yml config --quiet || {
            echo "❌ Existing Compose configuration is invalid; refusing upgrade."; exit 1;
        }
        volume=$(sudo docker volume inspect --format '{{.Name}}' amt-tandd_postgres_data)
        postgres_mount=$(sudo docker inspect --format '{{range .Mounts}}{{if eq .Destination "/var/lib/postgresql/data"}}{{.Type}}:{{.Name}}{{end}}{{end}}' tandd-postgres)
        app_data_mount=$(sudo docker inspect --format '{{range .Mounts}}{{if eq .Destination "/app/data"}}{{.Type}}:{{.Source}}{{end}}{{end}}' tandd-app)
        app_ssl_mount=$(sudo docker inspect --format '{{range .Mounts}}{{if eq .Destination "/etc/nginx/ssl"}}{{.Type}}:{{.Source}}{{end}}{{end}}' tandd-app)
        backup_mount=$(sudo docker inspect --format '{{range .Mounts}}{{if eq .Destination "/backups"}}{{.Type}}:{{.Source}}{{end}}{{end}}' tandd-backup)
        app_image=$(sudo docker inspect --format '{{.Config.Image}}' tandd-app)
        postgres_image=$(sudo docker inspect --format '{{.Config.Image}}' tandd-postgres)
        backup_image=$(sudo docker inspect --format '{{.Config.Image}}' tandd-backup)
        [ "$volume" = amt-tandd_postgres_data ] && \
            [ "$postgres_mount" = volume:amt-tandd_postgres_data ] && \
            [ "$app_data_mount" = bind:/opt/amt-tandd/tandd-data ] && \
            [ "$app_ssl_mount" = bind:/opt/amt-tandd/ssl-certs ] && \
            [ "$backup_mount" = bind:/opt/amt-tandd/tandd-data/backups ] && \
            [ "$postgres_image" = postgres:16-alpine ] && [ "$backup_image" = postgres:16-alpine ] || {
            echo "❌ Existing database volume, image, or durable mounts do not match the supported layout."
            exit 1
        }
        if [ "$LEGACY_UPGRADE" = true ] && [ "$app_image" != ghcr.io/dev-adanware/tanddsrv:1.23.1 ]; then
            echo "❌ Legacy migration preflight changed while being checked."; exit 1
        fi
    else
        partial_marker=/opt/amt-tandd/.lic3-install-in-progress
        if sudo test -e "$partial_marker" || sudo test -L "$partial_marker"; then
            if ! partial_install_marker_is_valid /opt/amt-tandd; then
                echo "❌ Partial installation marker or layout is unsafe; refusing automatic resume." >&2
                exit 1
            fi
            PARTIAL_INSTALL_RESUME=true
            PARTIAL_INSTALL_MARKER_PRESENT=true
            cleanup_partial_install_temps /opt/amt-tandd || exit 1
            echo "ℹ️  Resuming the script-marked partial LIC-3 fresh installation."
        elif legacy_partial_install_preflight_adopt /opt/amt-tandd; then
            PARTIAL_INSTALL_RESUME=true
            LEGACY_PARTIAL_ADOPTED=true
            echo "ℹ️  Adopting the verified pre-Compose partial state from the earlier LIC-3 installer."
        fi
        if sudo docker inspect tandd-app >/dev/null 2>&1; then
            echo "❌ An application container exists without a verified Compose project; refusing resume."
            exit 1
        fi
        if [ "$LEGACY_PARTIAL_ADOPTED" = true ] && sudo docker volume inspect amt-tandd_postgres_data >/dev/null 2>&1; then
            echo "❌ A PostgreSQL volume appeared during legacy partial-state adoption; refusing to continue." >&2
            exit 1
        fi
        if sudo docker volume inspect amt-tandd_postgres_data >/dev/null 2>&1 && [ "$PARTIAL_INSTALL_RESUME" != true ]; then
            echo "❌ Existing application container or PostgreSQL volume has no verified Compose project."
            exit 1
        fi
        if [ "$PARTIAL_INSTALL_RESUME" != true ]; then
            for path in /opt/amt-tandd/.env /opt/amt-tandd/docker-compose.yml; do
                if [ -e "$path" ] || [ -L "$path" ]; then
                    echo "❌ Existing installation data has no verified AMT T&D Compose project."
                    exit 1
                fi
            done
            for path in /opt/amt-tandd/tandd-data /opt/amt-tandd/ssl-certs; do
                if [ -L "$path" ] || { [ -e "$path" ] && { [ ! -d "$path" ] || [ -n "$(find "$path" -mindepth 1 -print -quit 2>/dev/null)" ]; }; }; then
                    echo "❌ Existing installation data has no verified AMT T&D Compose project."
                    exit 1
                fi
            done
        fi
    fi
else
    echo "❌ Unable to inspect Docker Compose project before installation."
    exit 1
fi

# Check connectivity to GHCR
if ! curl -s https://ghcr.io > /dev/null; then
    echo "❌ Cannot reach ghcr.io. Check firewall or outbound access."
    exit 1
else
    echo "✅ Internet / GHCR connectivity verified"
fi

echo "---------------------------------------------"

### -------------------------------
### 3. CREATE WORKING DIRECTORY
### -------------------------------

echo "Creating working directory..."

if [ "$FRESH_INSTALL" = true ] && [ "$PARTIAL_INSTALL_MARKER_PRESENT" != true ]; then
    create_partial_install_marker /opt/amt-tandd || {
        echo "❌ Unable to create the protected partial-install marker." >&2; exit 1;
    }
fi

for trust_path in /opt/amt-tandd /opt/amt-tandd/licensing /opt/amt-tandd/licensing/public_keys; do
    if sudo test -L "$trust_path" || { sudo test -e "$trust_path" && ! sudo test -d "$trust_path"; }; then
        echo "❌ Public-key trust path is unsafe: $trust_path" >&2
        exit 1
    fi
done
sudo mkdir -p /opt/amt-tandd/tandd-data
sudo mkdir -p /opt/amt-tandd/tandd-data/backups
sudo mkdir -p /opt/amt-tandd/tandd-data/licensing
sudo chmod 700 /opt/amt-tandd/tandd-data/licensing
sudo mkdir -p /opt/amt-tandd/licensing/public_keys
sudo chmod 755 /opt/amt-tandd/licensing/public_keys
for index in "${!PRODUCTION_KEY_IDS[@]}"; do
    key_id="${PRODUCTION_KEY_IDS[$index]}"
    target_key="/opt/amt-tandd/licensing/public_keys/$key_id.pem"
    expected="${PRODUCTION_FINGERPRINTS[$index]}"
    pem="${PRODUCTION_KEY_PEMS[$index]}"
    actual="$(printf '%s\n' "$pem" | openssl pkey -pubin -outform DER 2>/dev/null | sha256sum | awk '{print $1}')" || { echo "❌ Invalid public key: $key_id" >&2; exit 1; }
    [ "$actual" = "$expected" ] || { echo "❌ Approved trust key fingerprint mismatch: $key_id" >&2; exit 1; }
    if [ -e "$target_key" ] || [ -L "$target_key" ]; then
        [ -f "$target_key" ] && [ ! -L "$target_key" ] || {
            echo "❌ Existing trust key is unsafe: $key_id" >&2; exit 1;
        }
        existing="$(openssl pkey -pubin -in "$target_key" -outform DER 2>/dev/null | sha256sum | awk '{print $1}')" || existing=
        [ "$existing" = "$expected" ] || {
            echo "❌ Existing trust key conflicts with approved identity: $key_id" >&2; exit 1;
        }
    else
        key_tmp="$(sudo mktemp "/opt/amt-tandd/licensing/public_keys/.$key_id.pem.tmp.XXXXXX")"
        if ! printf '%s\n' "$pem" | sudo tee "$key_tmp" >/dev/null; then
            sudo rm -f -- "$key_tmp"; exit 1
        fi
        staged="$(sudo openssl pkey -pubin -in "$key_tmp" -outform DER 2>/dev/null | sha256sum | awk '{print $1}')" || staged=
        [ "$staged" = "$expected" ] || { sudo rm -f -- "$key_tmp"; echo "❌ Staged trust key fingerprint mismatch: $key_id" >&2; exit 1; }
        sudo chown root:root "$key_tmp" && sudo chmod 0644 "$key_tmp"
        if ! sudo ln -- "$key_tmp" "$target_key"; then
            sudo rm -f -- "$key_tmp"; echo "❌ Could not publish trust key without overwrite: $key_id" >&2; exit 1
        fi
        sudo rm -f -- "$key_tmp"
    fi
done
TRUST_REGISTRY='{"format_version":1,"keys":[{"key_id":"adanware-prod-v2","file":"adanware-prod-v2.pem","der_sha256":"d77cd0fbc4b570191f811117bede664cf495eb4e48ea4571552c7d856f46911e","usage":"sign-and-verify"},{"key_id":"production-2026","file":"production-2026.pem","der_sha256":"a1dae0d846ac59f26541d49b8b7d6264949a54b8dedfc28c08875c7703480244","usage":"verify-only","source_archive_sha256":"43eb130aadd3c8636014cb62ed364ddb405f4619be29206da89946cbc3a5df9a"}]}'
registry_path=/opt/amt-tandd/licensing/public_keys/registry.json
if [ -e "$registry_path" ] || [ -L "$registry_path" ]; then
    [ -f "$registry_path" ] && [ ! -L "$registry_path" ] && [ "$(cat "$registry_path")" = "$TRUST_REGISTRY" ] || { echo "❌ Existing trust registry conflicts with approved metadata" >&2; exit 1; }
else
    registry_tmp="$(sudo mktemp "/opt/amt-tandd/licensing/public_keys/.registry.json.tmp.XXXXXX")"
    if ! printf '%s\n' "$TRUST_REGISTRY" | sudo tee "$registry_tmp" >/dev/null; then
        sudo rm -f -- "$registry_tmp"; exit 1
    fi
    sudo chown root:root "$registry_tmp" && sudo chmod 0644 "$registry_tmp"
    if ! sudo ln -- "$registry_tmp" "$registry_path"; then
        sudo rm -f -- "$registry_tmp"; echo "❌ Could not publish trust registry without overwrite." >&2; exit 1
    fi
    sudo rm -f -- "$registry_tmp"
fi
for key in /opt/amt-tandd/licensing/public_keys/*; do
    [ -e "$key" ] || continue
    [ "${key##*/}" = registry.json ] && [ -f "$key" ] && [ ! -L "$key" ] && continue
    [ -f "$key" ] && [ ! -L "$key" ] && [[ "$key" == *.pem ]] || { echo "❌ Unexpected or unsafe trust entry: $key" >&2; exit 1; }
    ! grep -Eqi -- '-----BEGIN ([A-Z0-9 ]+ )?PRIVATE KEY-----' "$key" || { echo "❌ Private key material is forbidden in the trust directory" >&2; exit 1; }
done
sudo mkdir -p /opt/amt-tandd/ssl-certs
sudo chown -R "$(id -u):$(id -g)" /opt/amt-tandd
if [ "$FRESH_INSTALL" = true ] || [ "$PARTIAL_INSTALL_RESUME" = true ]; then
    sudo chown root:root /opt/amt-tandd/.lic3-install-in-progress
    sudo chmod 0600 /opt/amt-tandd/.lic3-install-in-progress
fi
sudo chown -R root:root /opt/amt-tandd/licensing
cd /opt/amt-tandd

echo "✅ Working directory ready"
echo "ℹ️  Data directory: /opt/amt-tandd/tandd-data"
echo "ℹ️  Backups directory: /opt/amt-tandd/tandd-data/backups"
echo "ℹ️  Durable licensing data: /opt/amt-tandd/tandd-data/licensing"
echo "ℹ️  Trusted public keys: /opt/amt-tandd/licensing/public_keys"
echo "✅ Provisioned adanware-prod-v2 (sign/verify) and production-2026 (verify-only) trust keys."
echo "ℹ️  SSL certificates directory: /opt/amt-tandd/ssl-certs"

### -------------------------------
### 3b. BACKUP EXISTING SSL CERTIFICATES
### -------------------------------

SSL_BACKUP_DIR="/tmp/tandd-ssl-backup-$(date +%Y%m%d%H%M%S)"
SSL_RESTORED=false

if [ -f /opt/amt-tandd/ssl-certs/cert.pem ] && [ -f /opt/amt-tandd/ssl-certs/key.pem ]; then
    echo "🔐 Existing SSL certificate found - backing up before deployment..."
    mkdir -p $SSL_BACKUP_DIR
    cp /opt/amt-tandd/ssl-certs/cert.pem $SSL_BACKUP_DIR/cert.pem
    cp /opt/amt-tandd/ssl-certs/key.pem $SSL_BACKUP_DIR/key.pem
    [ -f /opt/amt-tandd/ssl-certs/server.key ] && cp /opt/amt-tandd/ssl-certs/server.key $SSL_BACKUP_DIR/server.key
    [ -f /opt/amt-tandd/ssl-certs/server.csr ] && cp /opt/amt-tandd/ssl-certs/server.csr $SSL_BACKUP_DIR/server.csr
    SSL_RESTORED=true
    echo "✅ SSL certificates backed up to: $SSL_BACKUP_DIR"
else
    echo "ℹ️  No existing SSL certificate found - will generate CSR for IT department"
fi

### -------------------------------
### 4. DOCKER LOGIN (optional - only needed for private images)
### -------------------------------

echo "Authenticating with GitHub Container Registry..."
if echo "$GITHUB_TOKEN" | sudo docker login ghcr.io -u "$GITHUB_USERNAME" --password-stdin 2>/dev/null; then
    echo "✅ Docker authenticated successfully"
else
    echo "❌ Authentication failed! Check your GitHub username and token."
    exit 1
fi

### -------------------------------
### 5. CREATE ENVIRONMENT FILE
### -------------------------------

echo "Creating environment configuration..."

# Preserve existing .env on redeployment
if [ -f /opt/amt-tandd/.env ]; then
    echo "  ✓ Existing .env file found - preserving database credentials"
    source /opt/amt-tandd/.env
else
    # Generate secure password if not provided (first-time deploy only)
    if [ -z "$POSTGRES_PASSWORD" ]; then
        POSTGRES_PASSWORD=$(openssl rand -base64 32 | tr -d "=+/" | cut -c1-25)
        echo "✅ Generated secure database password"
    fi

    if [ "$FRESH_INSTALL" = true ]; then
        [[ "$POSTGRES_DB" =~ ^[a-zA-Z_][a-zA-Z0-9_]{0,52}$ ]] || {
            echo "❌ PostgreSQL database name must be a safe identifier of at most 53 characters for Restore staging." >&2; exit 1;
        }
        TANDD_APP_PASSWORD=$(openssl rand -hex 32)
        TANDD_BACKUP_PASSWORD=$(openssl rand -hex 32)
        TANDD_STAGING_PASSWORD=$(openssl rand -hex 32)
        TANDD_CUTOVER_PASSWORD=$(openssl rand -hex 32)
    fi

    # Publish .env atomically so an interrupted write can be retried safely.
    JWT_SECRET_KEY=$(openssl rand -hex 32)
    ENV_FILE_TMP="$(sudo mktemp /opt/amt-tandd/.env.tmp.XXXXXX)"
    if ! sudo tee "$ENV_FILE_TMP" >/dev/null << EOF
# PostgreSQL Database Configuration
POSTGRES_DB=${POSTGRES_DB}
POSTGRES_USER=${POSTGRES_USER}
POSTGRES_PASSWORD=${POSTGRES_PASSWORD}
JWT_SECRET_KEY=${JWT_SECRET_KEY}
TANDD_COORDINATOR_PG_PORT=55432
TANDD_APP_DATABASE_URL=postgresql://tandd_cutover:${TANDD_CUTOVER_PASSWORD:-}@postgres:5432/${POSTGRES_DB}
TANDD_APP_PASSWORD=${TANDD_APP_PASSWORD:-}
TANDD_BACKUP_POSTGRES_USER=tandd_backup
TANDD_BACKUP_POSTGRES_PASSWORD=${TANDD_BACKUP_PASSWORD:-}
TANDD_STAGING_PASSWORD=${TANDD_STAGING_PASSWORD:-}
TANDD_CUTOVER_PASSWORD=${TANDD_CUTOVER_PASSWORD:-}

# Backup Configuration
BACKUP_RETENTION_DAYS=7
EOF
    then
        sudo rm -f -- "$ENV_FILE_TMP"; exit 1
    fi
    sudo chmod 0600 "$ENV_FILE_TMP"
    if ! sudo ln -- "$ENV_FILE_TMP" /opt/amt-tandd/.env; then
        sudo rm -f -- "$ENV_FILE_TMP"
        echo "❌ Could not publish the initial environment file without overwriting an existing file." >&2
        exit 1
    fi
    sudo rm -f -- "$ENV_FILE_TMP"

    echo "✅ Environment file created"
fi

# JWT signing material is per installation and stays in the root-owned .env.
# Backfill existing installations once; later deployments preserve it.
JWT_SECRET_COUNT=$(grep -c '^JWT_SECRET_KEY=' /opt/amt-tandd/.env || true)
if [ "$JWT_SECRET_COUNT" -eq 0 ]; then
    ENV_FILE_TMP="$(sudo mktemp /opt/amt-tandd/.env.tmp.XXXXXX)"
    sudo cp -p /opt/amt-tandd/.env "$ENV_FILE_TMP"
    printf '\nJWT_SECRET_KEY=%s\n' "$(openssl rand -hex 32)" | sudo tee -a "$ENV_FILE_TMP" >/dev/null
    sudo chmod 0600 "$ENV_FILE_TMP"
    sudo mv -fT -- "$ENV_FILE_TMP" /opt/amt-tandd/.env
fi
if ! validate_jwt_secret_env /opt/amt-tandd/.env; then
    exit 1
fi
# Compose gives exported process variables precedence over its project .env.
# Use only the validated installation value for all subsequent Compose commands.
unset JWT_SECRET_KEY

### -------------------------------
### 6. CREATE DOCKER COMPOSE FILE
### -------------------------------

echo "Creating docker-compose configuration..."

if [ "$LEGACY_UPGRADE" = true ]; then
    LEGACY_COMPOSE_BACKUP="/opt/amt-tandd/docker-compose.yml.pre-v1.23.2-$(date -u +%Y%m%dT%H%M%SZ)"
    [ ! -e "$LEGACY_COMPOSE_BACKUP" ] || { echo "❌ Existing legacy Compose backup path; refusing overwrite."; exit 1; }
    sudo cp -a /opt/amt-tandd/docker-compose.yml "$LEGACY_COMPOSE_BACKUP"
fi

sudo tee /opt/amt-tandd/backup_postgres.sh >/dev/null <<'BACKUP_SCRIPT'
#!/bin/sh
# POSIX PostgreSQL backup scheduler and atomic backup publisher.
set -eu
umask 077

BACKUP_DIR=${BACKUP_DIR:-/backups}
BACKUP_CRON=${BACKUP_CRON-"0 2 * * *"}
BACKUP_RETENTION_DAYS=${BACKUP_RETENTION_DAYS:-7}
BACKUP_FORMAT=${BACKUP_FORMAT:-custom}
DB_HOST=${POSTGRES_HOST:-postgres}
DB_PORT=${POSTGRES_PORT:-5432}
DB_NAME=${POSTGRES_DB:-tandd}
DB_USER=${POSTGRES_USER:-tandd_user}

fail() {
    printf '%s\n' "backup error: $*" >&2
    cleanup_temporary_files
    return 1
}

normalize_minute() {
    case "$1" in
        [0-9]) MINUTE=$1 ;;
        0[0-9]) MINUTE=${1#0}; [ -n "$MINUTE" ] || MINUTE=0 ;;
        [1-5][0-9]) MINUTE=$1 ;;
        *) return 1 ;;
    esac
}

normalize_hour() {
    case "$1" in
        [0-9]) HOUR=$1 ;;
        0[0-9]) HOUR=${1#0}; [ -n "$HOUR" ] || HOUR=0 ;;
        1[0-9]) HOUR=$1 ;;
        2[0-3]) HOUR=$1 ;;
        *) return 1 ;;
    esac
}

validate_schedule() {
    set -f
    set -- $BACKUP_CRON
    set +f
    [ "$#" -eq 5 ] || { fail "BACKUP_CRON must be a daily five-field schedule (minute hour * * *)"; return 1; }
    normalize_minute "$1" && normalize_hour "$2" || {
        fail "BACKUP_CRON minute/hour must be decimal minute 0-59 and hour 0-23"; return 1;
    }
    [ "$3" = '*' ] && [ "$4" = '*' ] && [ "$5" = '*' ] || {
        fail "BACKUP_CRON supports only daily minute hour * * * schedules"; return 1;
    }
}

validate_retention() {
    case "$BACKUP_RETENTION_DAYS" in
        ''|*[!0-9]*) fail "BACKUP_RETENTION_DAYS must be a decimal integer from 0 to 3650"; return 1 ;;
    esac
    RETENTION_DAYS=$BACKUP_RETENTION_DAYS
    while [ "${RETENTION_DAYS#0}" != "$RETENTION_DAYS" ]; do
        RETENTION_DAYS=${RETENTION_DAYS#0}
    done
    [ -n "$RETENTION_DAYS" ] || RETENTION_DAYS=0
    [ "${#RETENTION_DAYS}" -le 4 ] || { fail "BACKUP_RETENTION_DAYS must be from 0 to 3650"; return 1; }
    [ "$RETENTION_DAYS" -le 3650 ] || { fail "BACKUP_RETENTION_DAYS must be from 0 to 3650"; return 1; }
}

next_delay() {
    case "$1" in
        ''|*[!0-9]*) fail "current epoch must be a decimal integer"; return 1 ;;
    esac
    EPOCH=$1
    while [ "${EPOCH#0}" != "$EPOCH" ]; do EPOCH=${EPOCH#0}; done
    [ -n "$EPOCH" ] || EPOCH=0
    [ "${#EPOCH}" -le 12 ] || { fail "current epoch is out of range"; return 1; }
    TARGET=$((HOUR * 3600 + MINUTE * 60))
    NOW_OF_DAY=$((EPOCH % 86400))
    DELAY=$(((TARGET - NOW_OF_DAY + 86400) % 86400))
    [ "$DELAY" -ne 0 ] || DELAY=86400
    printf '%s\n' "$DELAY"
}

cleanup_temporary_files() {
    [ -z "${TEMP_SQL:-}" ] || rm -f "$TEMP_SQL"
    [ -z "${TEMP_GZ:-}" ] || rm -f "$TEMP_GZ"
    [ -z "${TEMP_VERIFY:-}" ] || rm -f "$TEMP_VERIFY"
    TEMP_SQL=
    TEMP_GZ=
    TEMP_VERIFY=
}

publish_verified_backup() {
    SOURCE_FILE=$1
    if ! ln "$SOURCE_FILE" "$BACKUP_FILE"; then
        fail "cannot publish verified backup without replacing an existing file"
        return 1
    fi
    if ! rm "$SOURCE_FILE"; then
        fail "verified backup was published but its temporary link could not be removed"
        return 1
    fi
}

perform_backup() {
    [ -n "$BACKUP_DIR" ] || { fail "BACKUP_DIR must not be empty"; return 1; }
    [ -n "${POSTGRES_PASSWORD:-}" ] || { fail "POSTGRES_PASSWORD is required"; return 1; }
    [ "$BACKUP_FORMAT" = custom ] || { fail "BACKUP_FORMAT must be custom"; return 1; }
    BACKUP_SUFFIX=dump
    mkdir -p "$BACKUP_DIR" || { fail "cannot create BACKUP_DIR"; return 1; }
    TIMESTAMP=$(date -u +%Y%m%d_%H%M%S) || { fail "cannot read UTC time"; return 1; }
    case "$TIMESTAMP" in ''|*[!0-9_]*) fail "invalid UTC timestamp"; return 1 ;; esac
    BACKUP_FILE="$BACKUP_DIR/tandd_backup_${TIMESTAMP}_$$.$BACKUP_SUFFIX"
    TEMP_SQL="$BACKUP_DIR/.tandd_backup_${TIMESTAMP}_$$.sql.tmp"
    TEMP_GZ="$BACKUP_DIR/.tandd_backup_${TIMESTAMP}_$$.sql.gz.tmp"
    TEMP_VERIFY="$BACKUP_DIR/.tandd_backup_${TIMESTAMP}_$$.verify.tmp"
    trap cleanup_temporary_files 0 HUP INT TERM

    printf '%s\n' "creating PostgreSQL backup at $(date -u)"
    if [ "$BACKUP_FORMAT" = custom ]; then
        if ! PGPASSWORD=$POSTGRES_PASSWORD pg_dump \
            -h "$DB_HOST" -p "$DB_PORT" -U "$DB_USER" -d "$DB_NAME" \
            --no-owner --no-acl -Fc > "$TEMP_SQL"; then
            fail "pg_dump failed; previous backups were preserved"
            return 1
        fi
        if [ ! -s "$TEMP_SQL" ] || ! pg_restore --list "$TEMP_SQL" > "$TEMP_VERIFY" || [ ! -s "$TEMP_VERIFY" ]; then
            fail "backup verification failed (empty or invalid custom dump); previous backups were preserved"
            return 1
        fi
        if ! publish_verified_backup "$TEMP_SQL"; then return 1; fi
        TEMP_SQL=
    fi
    printf '%s\n' "verified backup published: $BACKUP_FILE"

    if ! find "$BACKUP_DIR" -maxdepth 1 -type f -name "tandd_backup_*.$BACKUP_SUFFIX" \
        -mtime "+$RETENTION_DAYS" -delete; then
        fail "backup succeeded but retention cleanup failed"
        return 1
    fi
    cleanup_temporary_files
}

case "${1:-run}" in
    validate-schedule)
        validate_schedule
        printf '%02d:%02d UTC\n' "$HOUR" "$MINUTE"
        ;;
    next-delay)
        validate_schedule
        [ "$#" -eq 2 ] || { fail "usage: $0 next-delay EPOCH_SECONDS"; exit 2; }
        next_delay "$2"
        ;;
    backup-once)
        [ "$#" -eq 1 ] || { fail "usage: $0 backup-once"; exit 2; }
        validate_retention
        perform_backup
        ;;
    run)
        [ "$#" -eq 1 ] || { fail "usage: $0 [validate-schedule|next-delay EPOCH_SECONDS|backup-once]"; exit 2; }
        validate_schedule
        validate_retention
        printf '%s\n' "PostgreSQL backups scheduled daily at $(printf '%02d:%02d' "$HOUR" "$MINUTE") UTC"
        while :; do
            NOW=$(date -u +%s) || { fail "cannot calculate next UTC backup time"; sleep 60; continue; }
            DELAY=$(next_delay "$NOW") || { sleep 60; continue; }
            printf '%s\n' "next backup in ${DELAY}s"
            sleep "$DELAY"
            if ! perform_backup; then
                printf '%s\n' "backup failed; the next daily run remains scheduled and existing backups were retained" >&2
            fi
        done
        ;;
    *)
        fail "unknown command; use run, validate-schedule, next-delay, or backup-once"
        exit 2
        ;;
esac
BACKUP_SCRIPT
sudo chmod 0755 /opt/amt-tandd/backup_postgres.sh

# Package the host-side coordinator tools without enabling restore actions.
sudo install -d -o root -g root -m 0750 /opt/amt-tandd/restore_coordinator
for asset in coordinator.py preflight.py validation.py maintenance.py cutover.py; do
    publish_embedded_asset "$asset" /opt/amt-tandd/restore_coordinator 0644
 done
for asset in fresh_database.sh postgres_client.sh provision.sh; do
    publish_embedded_asset "$asset" /opt/amt-tandd/restore_coordinator 0755
 done
publish_embedded_asset OPERATOR_PROVISIONING.md /opt/amt-tandd/restore_coordinator 0644

cat > /opt/amt-tandd/docker-compose.yml << 'EOF'
name: amt-tandd

version: '3.8'

services:
  postgres:
    image: postgres:16-alpine
    container_name: tandd-postgres
    environment:
      POSTGRES_DB: ${POSTGRES_DB:-tandd}
      POSTGRES_USER: ${POSTGRES_USER:-tandd_user}
      POSTGRES_PASSWORD: ${POSTGRES_PASSWORD:-changeme123}
    volumes:
      - postgres_data:/var/lib/postgresql/data
      - ./tandd-data/backups:/backups
    ports:
      - "127.0.0.1:${TANDD_COORDINATOR_PG_PORT:-55432}:5432"
    restart: unless-stopped
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -U ${POSTGRES_USER:-tandd_user} -d ${POSTGRES_DB:-tandd}"]
      interval: 10s
      timeout: 5s
      retries: 5

  app:
    image: ghcr.io/dev-adanware/tanddsrv:APP_VERSION_PLACEHOLDER
    container_name: tandd-app
    environment:
      DATABASE_URL: ${TANDD_APP_DATABASE_URL:-postgresql://${POSTGRES_USER:-tandd_user}:${POSTGRES_PASSWORD:-changeme123}@postgres:5432/${POSTGRES_DB:-tandd}}
      TANDD_APPLICATION_VERSION: ${TANDD_APPLICATION_VERSION:-APP_VERSION_PLACEHOLDER}
      TANDD_RESTORE_MAX_UPLOAD_BYTES: ${TANDD_RESTORE_MAX_UPLOAD_BYTES:-2147483648}
      TANDD_MAINTENANCE_GATE_FILE: /run/tandd-maintenance/state.json
      APP_ENV: production
      LICENSE_ENFORCEMENT: required
      JWT_SECRET_KEY: ${JWT_SECRET_KEY:?JWT_SECRET_KEY is required in the installation .env}
      LICENSING_DATA_ROOT: /app/data
      LICENSE_PUBLIC_KEYS_DIR: /app/licensing/public_keys
    volumes:
      - ./tandd-data:/app/data
      - ./licensing/public_keys:/app/licensing/public_keys:ro
      - ./ssl-certs:/etc/nginx/ssl
      - /var/lib/tandd-restore/intake:/restore-intake
      - /run/tandd-restore:/run/tandd-restore:ro
      - /var/lib/tandd-restore/maintenance:/run/tandd-maintenance:ro
    ports:
      - "80:80"
      - "443:443"
      - "21:21"
      - "60000-60100:60000-60100"
    depends_on:
      postgres:
        condition: service_healthy
    restart: unless-stopped

  backup:
    image: postgres:16-alpine
    container_name: tandd-backup
    environment:
      POSTGRES_DB: ${POSTGRES_DB:-tandd}
      POSTGRES_USER: ${TANDD_BACKUP_POSTGRES_USER:-${POSTGRES_USER:-tandd_user}}
      POSTGRES_PASSWORD: ${TANDD_BACKUP_POSTGRES_PASSWORD:-${POSTGRES_PASSWORD:-changeme123}}
      BACKUP_RETENTION_DAYS: 7
      BACKUP_CRON: ${BACKUP_CRON:-0 2 * * *}
      BACKUP_FORMAT: custom
      BACKUP_DIR: /backups
    volumes:
      - ./tandd-data/backups:/backups
      - ./backup_postgres.sh:/backup.sh:ro
    depends_on:
      postgres:
        condition: service_healthy
    entrypoint: ["/bin/sh", "/backup.sh"]
    command: ["run"]
    restart: unless-stopped

volumes:
  postgres_data:
EOF

# Replace version placeholder
sed -i "s/APP_VERSION_PLACEHOLDER/${APP_VERSION}/g" /opt/amt-tandd/docker-compose.yml

echo "✅ Docker Compose file created"

### -------------------------------
### 7. PULL IMAGES
### -------------------------------

echo "Pulling Docker images..."

sudo docker pull postgres:16-alpine
sudo docker pull "ghcr.io/dev-adanware/tanddsrv:${APP_VERSION}"

echo "✅ Images pulled successfully"

sudo docker compose --project-name amt-tandd --project-directory /opt/amt-tandd \
    --file /opt/amt-tandd/docker-compose.yml config --quiet

if [ "$FRESH_INSTALL" = true ]; then
    sudo /opt/amt-tandd/restore_coordinator/postgres_client.sh install-online
    sudo chown root:root /opt/amt-tandd /opt/amt-tandd/docker-compose.yml /opt/amt-tandd/.env
    sudo chmod 0750 /opt/amt-tandd
    sudo chmod 0600 /opt/amt-tandd/.env
fi

# A missing maintenance gate is intentionally fail-closed by the app. Seed an
# inactive gate only for a verified fresh install; never replace existing state.
MAINTENANCE_DIR=/var/lib/tandd-restore/maintenance
MAINTENANCE_STATE="$MAINTENANCE_DIR/state.json"
if [ "$FRESH_INSTALL" = true ] && [ ! -e "$MAINTENANCE_STATE" ] && [ ! -L "$MAINTENANCE_STATE" ]; then
    if [ -L /var/lib/tandd-restore ] || [ -L "$MAINTENANCE_DIR" ]; then
        echo "❌ Restore maintenance path must not be a symlink." >&2
        exit 1
    fi
    sudo install -d -o root -g root -m 0755 "$MAINTENANCE_DIR"
    gate_tmp="$MAINTENANCE_DIR/.state.initial.$$"
    [ ! -e "$gate_tmp" ] && [ ! -L "$gate_tmp" ] || {
        echo "❌ Initial maintenance state path already exists." >&2; exit 1;
    }
    printf '%s\n' '{"maintenance":false,"phase":"inactive","operation_id":null,"started_at":null,"ended_at":null,"monitoring_gap_seconds":null,"error_code":null}' | sudo tee "$gate_tmp" >/dev/null
    sudo chown root:root "$gate_tmp"
    sudo chmod 0444 "$gate_tmp"
    if ! sudo ln "$gate_tmp" "$MAINTENANCE_STATE"; then
        sudo rm -f "$gate_tmp"
        if [ ! -e "$MAINTENANCE_STATE" ] && [ ! -L "$MAINTENANCE_STATE" ]; then
            echo "❌ Could not create the initial maintenance state." >&2
            exit 1
        fi
    else
        sudo rm -f "$gate_tmp"
    fi
fi

if [ "$LEGACY_UPGRADE" = true ]; then
    sudo "$EMBEDDED_ASSET_DIR/migrate_legacy_identity.sh" \
        /opt/amt-tandd "ghcr.io/dev-adanware/tanddsrv:${APP_VERSION}" "${APP_VERSION%%-*}"
fi

### -------------------------------
### 8. START SERVICES
### -------------------------------

echo "Starting services with Docker Compose..."

# Stop and remove old single container if exists
sudo docker stop tandd-app 2>/dev/null || true
sudo docker rm tandd-app 2>/dev/null || true

if [ "$FRESH_INSTALL" = true ]; then
    fresh_restore_fail_closed() {
        trap - ERR
        sudo docker compose --project-name amt-tandd --project-directory /opt/amt-tandd \
            --file /opt/amt-tandd/docker-compose.yml stop app backup >/dev/null 2>&1 || true
    }
    trap fresh_restore_fail_closed ERR
    image_user=$(sudo docker image inspect --format '{{.Config.User}}' "ghcr.io/dev-adanware/tanddsrv:${APP_VERSION}")
    if [ -n "$image_user" ] && [ "$image_user" != "0" ] && [ "$image_user" != "root" ]; then
        echo "❌ Fresh Restore provisioning requires the supported app image to run as root in its container." >&2
        exit 1
    fi
    sudo /opt/amt-tandd/restore_coordinator/provision.sh install \
        /opt/amt-tandd /opt/amt-tandd/docker-compose.yml 0 0 amt-tandd
    sudo docker compose --project-name amt-tandd --project-directory /opt/amt-tandd \
        --file /opt/amt-tandd/docker-compose.yml up -d postgres
    postgres_ready=false
    for attempt in $(seq 1 60); do
        if sudo docker compose --project-name amt-tandd --project-directory /opt/amt-tandd \
            --file /opt/amt-tandd/docker-compose.yml exec -T postgres pg_isready \
            -U "$POSTGRES_USER" -d "$POSTGRES_DB" >/dev/null 2>&1; then
            postgres_ready=true
            break
        fi
        sleep 2
    done
    if [ "$postgres_ready" != true ]; then
        echo "❌ PostgreSQL 16 did not become ready; Restore validation remains disabled." >&2
        exit 1
    fi
    sudo /opt/amt-tandd/restore_coordinator/fresh_database.sh provision \
        /opt/amt-tandd /opt/amt-tandd/docker-compose.yml
    sudo docker compose --project-name amt-tandd --project-directory /opt/amt-tandd \
        --file /opt/amt-tandd/docker-compose.yml up -d app
    sleep 20
    if ! sudo docker ps --format '{{.Names}}' | grep -qx tandd-app; then
        fresh_restore_fail_closed
        echo "❌ Application schema initialization failed; Restore remains disabled." >&2
        exit 1
    fi
    sudo /opt/amt-tandd/restore_coordinator/fresh_database.sh grant-objects \
        /opt/amt-tandd /opt/amt-tandd/docker-compose.yml
    sudo sed -i "s#^TANDD_APP_DATABASE_URL=.*#TANDD_APP_DATABASE_URL=postgresql://tandd_app:${TANDD_APP_PASSWORD}@postgres:5432/${POSTGRES_DB}#" /opt/amt-tandd/.env
    sudo sed -i '/^TANDD_APP_PASSWORD=/d; /^TANDD_STAGING_PASSWORD=/d; /^TANDD_CUTOVER_PASSWORD=/d' /opt/amt-tandd/.env
    sudo docker compose --project-name amt-tandd --project-directory /opt/amt-tandd \
        --file /opt/amt-tandd/docker-compose.yml up -d --force-recreate app backup
    sleep 15
    audit_report=$(sudo mktemp /var/lib/tandd-restore/fresh-install-audit.XXXXXXXX)
    sudo chmod 0600 "$audit_report"
    if ! sudo env PGSERVICEFILE=/etc/tandd-restore-coordinator.pg_service.conf \
        /usr/bin/python3 /opt/amt-tandd/restore_coordinator/preflight.py \
        --service-file /etc/tandd-restore-coordinator.pg_service.conf --service audit \
        --active-database "$POSTGRES_DB" --staging-database "${POSTGRES_DB}_staging" \
        --app-role tandd_app --backup-role tandd_backup --staging-role tandd_staging \
        --cutover-role tandd_cutover --project-dir /opt/amt-tandd \
        --compose-file /opt/amt-tandd/docker-compose.yml >"$audit_report"; then
        sudo docker compose --project-name amt-tandd --project-directory /opt/amt-tandd \
            --file /opt/amt-tandd/docker-compose.yml stop app backup || true
        echo "❌ PostgreSQL Restore privilege, ownership, or deployed-credential audit failed; validation remains disabled." >&2
        sudo cat "$audit_report" >&2
        exit 1
    fi
    sudo /opt/amt-tandd/restore_coordinator/provision.sh enable-audited "$audit_report"
    sudo rm -f "$audit_report"
    trap - ERR
else
    sudo docker compose --project-name amt-tandd --project-directory /opt/amt-tandd \
        --file /opt/amt-tandd/docker-compose.yml up -d
fi

echo "✅ Services started (PostgreSQL + Application + Backup)"

### -------------------------------
### 9. VERIFY DEPLOYMENT
### -------------------------------

echo "Waiting for services to start..."
sleep 15

if sudo docker ps --format '{{.Names}}' | grep -qx tandd-postgres; then
    echo "✅ PostgreSQL database is running"
else
    echo "❌ PostgreSQL failed to start"
    exit 1
fi

if sudo docker ps --format '{{.Names}}' | grep -qx tandd-app; then
    echo "✅ Application is running"
else
    echo "❌ Application failed to start"
    exit 1
fi

if sudo docker ps --format '{{.Names}}' | grep -qx tandd-backup; then
    echo "✅ Backup service is running"
else
    echo "❌ Backup service failed to start; partial-install state is retained for safe recovery." >&2
    exit 1
fi

SERVER_IP=$(hostname -I | awk '{print $1}')

echo "---------------------------------------------"
echo "🎉 Deployment Completed Successfully!"
echo "---------------------------------------------"
echo ""
echo "📊 SERVICES RUNNING:"
echo "  • PostgreSQL Database (with automatic backups)"
echo "  • T&D Data Server Application"
echo "  • Daily Backup Service (7-day retention)"
echo ""
echo "🌐 ACCESS THE APPLICATION:"
echo "  HTTP:  http://$SERVER_IP/"
echo "  HTTPS: https://$SERVER_IP/ (self-signed certificate)"
echo ""
echo "ℹ️  HTTPS uses auto-generated self-signed certificate."
echo "   Browsers will show a warning - this is normal."
echo "   Click 'Advanced' → 'Proceed' to access."
echo ""
echo "🔐 TO USE PROPER SSL CERTIFICATE FROM IT:"
echo "   1. Place IT's certificates in /opt/amt-tandd/ssl-certs/"
echo "      - cert.pem (certificate file)"
echo "      - key.pem (private key file)"
echo "   2. Restart: cd /opt/amt-tandd && sudo docker compose restart app"
echo ""
echo "💾 DATABASE BACKUPS:"
echo "   Location: /opt/amt-tandd/tandd-data/backups/"
echo "   Schedule: Daily at midnight"
echo "   Retention: 7 days"
echo ""
echo "📝 CREDENTIALS SAVED IN:"
echo "   /opt/amt-tandd/.env"
echo "   ⚠️  Keep this file secure!"
echo "---------------------------------------------"

if curl -s http://localhost/ > /dev/null; then
    echo "✅ Web application is responding and ready to use!"
else
    echo "⚠️  Application started but not responding yet. Wait 30 seconds and try again."
fi

### -------------------------------
### 10. SSL CERTIFICATE HANDLING
### -------------------------------

echo ""
echo "---------------------------------------------"
echo "� SSL CERTIFICATE HANDLING"
echo "---------------------------------------------"

if [ "$SSL_RESTORED" = true ]; then
    echo "♻️  Restoring previously installed SSL certificate..."
    cp $SSL_BACKUP_DIR/cert.pem /opt/amt-tandd/ssl-certs/cert.pem
    cp $SSL_BACKUP_DIR/key.pem /opt/amt-tandd/ssl-certs/key.pem
    [ -f $SSL_BACKUP_DIR/server.key ] && cp $SSL_BACKUP_DIR/server.key /opt/amt-tandd/ssl-certs/server.key
    [ -f $SSL_BACKUP_DIR/server.csr ] && cp $SSL_BACKUP_DIR/server.csr /opt/amt-tandd/ssl-certs/server.csr
    echo "✅ SSL certificate restored successfully!"

    # Restart app to pick up restored certificate
    echo "🔄 Restarting app to apply restored certificate..."
    cd /opt/amt-tandd
    sudo docker compose restart app
    sleep 5
    echo "✅ App restarted with original SSL certificate"

    # Clean up temp backup
    rm -rf $SSL_BACKUP_DIR
    echo "✅ Temporary backup cleaned up"
else
    echo "📋 GENERATING CERTIFICATE SIGNING REQUEST (CSR)"
    echo ""
    echo "Generating CSR file for IT department..."

    # Determine Common Name (CN) for certificate
    if [ -z "$SSL_HOSTNAME" ]; then
        CERT_CN=$(hostname -f 2>/dev/null || hostname -I | awk '{print $1}')
        echo "  Auto-detected server identifier: $CERT_CN"
    else
        CERT_CN="$SSL_HOSTNAME"
        echo "  Using custom hostname: $CERT_CN"
    fi

    # Generate CSR and private key for IT
    openssl req -new -newkey rsa:2048 -nodes \
        -keyout /opt/amt-tandd/ssl-certs/server.key \
        -out /opt/amt-tandd/ssl-certs/server.csr \
        -subj "/C=${SSL_COUNTRY}/ST=${SSL_STATE}/L=${SSL_CITY}/O=${SSL_ORGANIZATION}/CN=${CERT_CN}" \
        2>/dev/null

    echo "✅ CSR generated successfully!"
    echo ""
    echo "📧 SEND THIS FILE TO YOUR IT DEPARTMENT:"
    echo "   File: /opt/amt-tandd/ssl-certs/server.csr"
    echo ""
    echo "📄 CSR CONTENT:"
    echo "---------------------------------------------"
    cat /opt/amt-tandd/ssl-certs/server.csr
    echo "---------------------------------------------"
    echo ""
    echo "🔧 AFTER RECEIVING CERTIFICATE FROM IT:"
    echo "   1. Save as: /opt/amt-tandd/ssl-certs/cert.pem"
    echo "   2. Run: sudo cp /opt/amt-tandd/ssl-certs/server.key /opt/amt-tandd/ssl-certs/key.pem"
    echo "   3. Run: cd /opt/amt-tandd && sudo docker compose restart app"
    echo ""
fi

echo "---------------------------------------------"
echo ""
echo "📚 For more information, visit the documentation."
echo "🆘 For support, contact ADANWARE."
echo ""

for required_container in tandd-postgres tandd-app tandd-backup; do
    if ! sudo docker ps --format '{{.Names}}' | grep -qx "$required_container"; then
        echo "❌ Required service $required_container is not running after SSL handling; partial-install state is retained." >&2
        exit 1
    fi
done

if [ "$FRESH_INSTALL" = true ] || [ "$PARTIAL_INSTALL_RESUME" = true ]; then
    remove_partial_install_marker /opt/amt-tandd || exit 1
fi
